// Virtual Address Structure (32-bit architecture, 4KB pages)
const int PAGE_OFFSET_BITS = 12;

typedef struct {
    uint32_t offset : PAGE_OFFSET_BITS;        // Displacement within the page
    uint32_t page_number : (32 - PAGE_OFFSET_BITS); // Index into the Page Table
} VirtualAddress;

// Single-Level Page Table Entry (PTE)
typedef struct {
    uint32_t present : 1;   // Must be set for valid translation
    uint32_t write : 1;     // Permissions
    uint32_t accessed : 1;
    // ... other flags (Dirty, User/Supervisor, etc.)
    uint32_t frame_number : 20; // Physical Page Frame Number (PPFN)
} PageTableEntry;

// Translation (Conceptual Step)
// PA = (Frame Number << PAGE_OFFSET_BITS) | Offset
phys_addr_t translate(PageTableEntry pte, VirtualAddress va) {
    if (!pte.present) { /* Handle Page Fault */ }
    return (pte.frame_number << PAGE_OFFSET_BITS) | va.offset;
}
